function drawTower(type,level,x,y){const size=[103,118,135,150,166][level-1],s=towerSprites[(level-1)*8+TYPES[type].sprite];if(s)ctx.drawImage(s,x-size*.5,y-size*.94,size,size);else if(TYPES[type].sprite<5)drawSprite(TYPES[type].sprite,x,y,size);}
