  if(e.slow>0)ellipse(e.x,e.y,size*.3,size*.12,null,'#bdeaff',1);
  if(e.curse>0)ellipse(e.x,e.y-8,size*.3,size*.1,null,'#83f2d8',1.4);
  if(e.burn>0){for(let i=0;i<3;i++){const p=(clock*1.8+i/3)%1;ctx.globalAlpha=1-p;ellipse(e.x+(i-1)*7,e.y-8-p*25,2*(1-p)+.6,4*(1-p)+1,'#ffae4d');}ctx.globalAlpha=1;}
