 ctx.fillStyle=game.mapIndex===2?'#674477':'#315d99';ctx.beginPath();ctx.moveTo(bx+1,by+2);ctx.bezierCurveTo(bx+8,by+wave,bx+15,by+6-wave,bx+22,by+2+wave);ctx.lineTo(bx+20,by+15+wave);ctx.bezierCurveTo(bx+12,by+19-wave,bx+8,by+12+wave,bx+1,by+15);ctx.closePath();ctx.fill();ctx.strokeStyle='#d5b36b';ctx.lineWidth=.6;ctx.stroke();
 if(!reducedMotion&&game.mapIndex!==1){for(let i=0;i<7;i++){const x=682+i*14+Math.sin(clock*.5+i)*2,y=142+Math.sin(i*1.4)*9;ctx.globalAlpha=.10+.08*Math.sin(clock*2+i);ctx.strokeStyle='#d3f4e7';ctx.lineWidth=.9;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+5+Math.sin(clock+i)*2,y-1);ctx.stroke();}ctx.globalAlpha=1;}
